-- National source expansion: prioritize structured Black Chamber directories and stage broader national directories for parser QA.
on conflict(source_key) do update set source_name=excluded.source_name,adapter=excluded.adapter,base_url=excluded.base_url,ownership_signal=excluded.ownership_signal,priority=excluded.priority,notes=excluded.notes,active=excluded.active,updated_at=now();

-- Seed A-shard QA jobs for the new structured chamber sources. Weekly A-Z refresh is already handled by black_pages_internal_queue_adapter('growthzone_v2').
select s.source_key,null,null,null,1,regexp_replace(s.base_url,'term=.*$','term=A'),100,'pending',0,null,null,null,0,now()
from public.black_pages_external_sources s
where s.source_key in('central_florida_african_american_chamber','san_joaquin_black_owned_directory','nashville_black_chamber','oklahoma_city_black_chamber')
on conflict(source_key,request_url) do update set status='pending',attempt_count=0,error_message=null,started_at=null,completed_at=null,result_count=0,updated_at=now();
